// any JS signal handler fires. Restricting this behavior to TUI commands
// avoids breaking Ctrl+C for non-TUI commands like `opencode serve`.
if (process.platform === "win32") {
  const argv = hideBin(process.argv)
  const cmd = argv[0]
  const sub = argv[1]

